CROSS JOIN (
  SELECT artefact_value_id, artefact_value
  FROM artefact_values
  WHERE artefact_id = 7
    AND artefact_value = 'AI-модели партнерств'
  LIMIT 1
) tv
WHERE NOT EXISTS (
  SELECT 1
  FROM artefact_realizations ar
  WHERE ar.model_id = tm.model_id
    AND ar.artefact_id = 7
    AND ar.effective_to = to_timestamp('9999-12-31 23:59:59', 'YYYY-MM-DD HH24:MI:SS')
    AND ar.artefact_string_value = 'AI-модели партнерств'
);

